const body = $input.first().json.body || $input.first().json;
let machineId = (body.machine_id || '').trim();
machineId = machineId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { machine_id: machineId } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
const m = arr[0] || null;
let text = '';
if (!m) {
  text = '未找到机台';
} else {
  text = `机台: ${m.id}\n型号: ${m.model || '未知'}\n状态: ${m.status || '未知'}\n当前Lot: ${m.current_lot_id || '无'}\n最近事件: ${m.last_event_ts || '无'}`;
}
return { json: { machine: m, summary: text } };
